import 'package:cupertino_ui/cupertino_ui.dart'
    show GlobalCupertinoLocalizations;
import 'package:flutter/widgets.dart';
import 'package:flutter_localizations/flutter_localizations.dart'
    show GlobalWidgetsLocalizations;
import 'package:material_ui/material_ui.dart' show GlobalMaterialLocalizations;
import 'package:pickstock/l10n/app_localizations.dart';

/// The app's localization delegates. `AppLocalizations.localizationsDelegates`
/// (generated by `flutter gen-l10n`) still registers the framework's
/// Material and Cupertino localizations, which the material_ui and
/// cupertino_ui widgets do not read (Flutter 3.47 moved Material and
/// Cupertino out of the framework); these are theirs.
const List<LocalizationsDelegate<Object?>> appLocalizationsDelegates = [
  AppLocalizations.delegate,
  GlobalMaterialLocalizations.delegate,
  GlobalCupertinoLocalizations.delegate,
  GlobalWidgetsLocalizations.delegate,
];
